// @r_peredelkino · local courtyard games, with no accounts, network or paid content.
export function createCourtyardActivities(host,{onClose=()=>{}}={}) {
  const dialog=document.createElement('dialog');dialog.className='courtyard-activity';
  dialog.setAttribute('aria-label','Кибердвор · мини-игры');
  dialog.innerHTML=`<header><div><small>КИБЕРДВОР / АВТОРСКАЯ КОНЦЕПЦИЯ</small><h2></h2></div><button data-close aria-label="Закрыть мини-игру">×</button></header><p data-intro></p><div class="cyber-game-result" role="status" aria-live="polite"></div><button class="cyber-reaction-pad" data-reaction hidden>Начать</button><div class="cyber-memory-grid" hidden>${['A','B','C','D'].map((v,i)=>`<button data-tile="${i}" aria-label="Клавиша ${v}">${v}</button>`).join('')}</div><div class="cyber-game-footer"><button data-start>Начать тренировку</button><span data-record></span></div><p class="cyber-game-caption">Небольшая игра для прогулки. Результат зависит от устройства и задержки кадра; это не оценка спортивных способностей.</p>`;
  host.append(dialog);
  const result=dialog.querySelector('.cyber-game-result'),pad=dialog.querySelector('[data-reaction]'),grid=dialog.querySelector('.cyber-memory-grid'),tiles=[...grid.querySelectorAll('button')],start=dialog.querySelector('[data-start]');
  let mode='reaction',phase='idle',timer=null,signalAt=0,round=0,samples=[],sequence=[],inputIndex=0,level=0,dead=false;
  const stop=()=>{clearTimeout(timer);timer=null;};
  const later=(fn,ms)=>{stop();timer=setTimeout(()=>{timer=null;if(!dead&&dialog.open)fn();},ms);};
  const announce=text=>result.textContent=text;
  const record=()=>{try{const ms=Number(localStorage.getItem('rodina-reaction-best-v1'));dialog.querySelector('[data-record]').textContent=ms>0?'Лучший средний результат: '+ms+' мс':'5 сигналов · ваш результат хранится на этом устройстве';}catch{dialog.querySelector('[data-record]').textContent='5 сигналов';}};
  function nextSignal(){phase='wait';pad.dataset.phase='wait';pad.textContent='Ждите световой сигнал';announce('Раунд '+(round+1)+' из 5');later(()=>{phase='signal';signalAt=performance.now();pad.dataset.phase='signal';pad.textContent='Сейчас! Нажмите';},900+Math.random()*1500);}
  function reaction(){if(mode!=='reaction')return;if(phase==='wait'){stop();phase='early';pad.dataset.phase='early';pad.textContent='Рано — дождитесь сигнала';announce('Фальстарт. Этот раунд повторяется.');later(nextSignal,850);return;}if(phase!=='signal')return;const ms=Math.round(performance.now()-signalAt);samples.push(ms);round++;phase='feedback';pad.dataset.phase='feedback';pad.textContent=ms+' мс';if(round<5){announce('Хорошо. Следующий сигнал…');later(nextSignal,800);}else{const mean=Math.round(samples.reduce((a,b)=>a+b,0)/samples.length);phase='done';pad.textContent='Среднее: '+mean+' мс';announce('Готово · '+samples.join(' / ')+' мс');start.disabled=false;start.textContent='Повторить';try{const prior=Number(localStorage.getItem('rodina-reaction-best-v1'));if(!(prior>0)||mean<prior)localStorage.setItem('rodina-reaction-best-v1',String(mean));}catch{}record();}}
  function showSequence(){phase='show';inputIndex=0;tiles.forEach(b=>{b.disabled=true;b.classList.remove('is-lit');});let i=0;announce('Запомните последовательность · уровень '+level);const light=()=>{if(i>=sequence.length){phase='input';tiles.forEach(b=>b.disabled=false);announce('Теперь повторите · '+sequence.length+' нажатий');return;}const b=tiles[sequence[i]];b.classList.add('is-lit');later(()=>{b.classList.remove('is-lit');i++;later(light,210);},480);};later(light,450);}
  function tile(index){if(mode!=='memory'||phase!=='input')return;if(index!==sequence[inputIndex]){phase='done';announce('Последовательность завершена. Пройдено уровней: '+(level-1));start.disabled=false;start.textContent='Попробовать ещё';return;}inputIndex++;if(inputIndex===sequence.length){if(level>=6){phase='done';announce('Все шесть уровней пройдены. Отличная командная память!');start.disabled=false;start.textContent='Повторить';}else{phase='show';tiles.forEach(b=>b.disabled=true);level++;sequence.push(Math.floor(Math.random()*4));announce('Верно! Следующий уровень · дождитесь показа…');later(showSequence,650);}}}
  function begin(){stop();round=0;samples=[];start.disabled=true;if(mode==='reaction')nextSignal();else{level=1;sequence=[Math.floor(Math.random()*4)];showSequence();}}
  function close(){if(!dialog.open)return;stop();phase='idle';dialog.close();tiles.forEach(b=>b.classList.remove('is-lit'));onClose();}
  function open(kind='reaction'){stop();mode=kind==='table'?'memory':'reaction';phase='idle';dialog.dataset.game=mode;dialog.querySelector('h2').textContent=mode==='reaction'?'Световая реакция':'Командная память';dialog.querySelector('[data-intro]').textContent=mode==='reaction'?'Дождитесь зелёного сигнала и нажмите большую кнопку или пробел. Пять коротких раундов.':'Тактический стол: запомните подсвеченные клавиши и повторите порядок. С каждым уровнем последовательность длиннее.';pad.hidden=mode!=='reaction';grid.hidden=mode!=='memory';pad.dataset.phase='idle';pad.textContent='Нажмите «Начать тренировку»';start.disabled=false;start.textContent='Начать тренировку';announce('Готовы?');tiles.forEach(b=>{b.disabled=true;b.classList.remove('is-lit');});record();dialog.showModal();start.focus({preventScroll:true});}
  const key=e=>{if(!dialog.open)return;if(e.code==='Escape'){e.preventDefault();e.stopImmediatePropagation();close();return;}if(e.code==='Space'&&mode==='reaction'&&(phase==='wait'||phase==='signal')){e.preventDefault();e.stopImmediatePropagation();if(!e.repeat)reaction();}};
  document.addEventListener('keydown',key,true);dialog.addEventListener('cancel',e=>{e.preventDefault();close();});dialog.querySelector('[data-close]').onclick=close;start.onclick=begin;pad.onclick=reaction;tiles.forEach((b,i)=>b.onclick=()=>tile(i));
  return{dialog,open,close,get enabled(){return dialog.open;},get state(){return{mode,phase,round,level,sequence:sequence.slice(),samples:samples.slice()};},dispose(){dead=true;close();stop();document.removeEventListener('keydown',key,true);dialog.remove();}};
}
